686	  // ----------------------------------------------------------------- cache
687	
688	  async cacheGet(key) {
689	    await this.loading;
690	    const normalized = assertCacheKey(key);
691	    const { manifest, buffer } = await this.store.readArtifact(normalized);
692	    return { manifest, buffer };
693	  }
694	
695	  // Ingest an action manifest. Any peer that knows a cached action key may push
696	  // the entry, and it is accepted only when every hashed field in the manifest
697	  // still recomputes to the key being claimed.
698	  async cachePut(key, entry, buffer) {
699	    await this.loading;
700	    const normalized = assertCacheKey(key);
701	    if (!isPlainObject(entry)) throw new ValidationError('cache entry must be a JSON object');
702	    rejectUnknown(entry, CACHE_ENTRY_FIELDS, 'cache entry');
703	    if (!isPlainObject(entry.command)) throw new ValidationError('cache entry command must be an object');
704	    if (!Array.isArray(entry.inputs) || !Array.isArray(entry.env)) {
705	      throw new ValidationError('cache entry inputs and env must be arrays');
706	    }
707	    for (const input of entry.inputs) {
708	      if (!isPlainObject(input)) throw new ValidationError('cache entry inputs must be objects');
709	      rejectUnknown(input, INPUT_FIELDS, 'cache entry input');
710	      if (input.kind !== 'file' && input.kind !== 'hash') {
711	        throw new ValidationError('cache entry input kind must be "file" or "hash"');
712	      }
713	    }
714	    const command = normalizeCommand(entry.command);
715	    const inputsValue = normalizeCacheInputs(entry.inputs);
716	    const names = entry.env.map((name) => {
717	      if (typeof name !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
718	        throw new ValidationError('cache entry env must be an array of variable names');
719	      }
720	      return name;
721	    });
722	    if (new Set(names).size !== names.length) {
723	      throw new ValidationError('cache entry env names must be unique');
724	    }
725	    // Copied so the manifest never aliases caller-owned state.
726	    const inputs = inputsValue.map((input) => ({ ...input }));
727	    const env = { names: [...names].sort(), values: {} };
728	    const recomputed = actionKey({ command, inputs, env });
729	    if (recomputed !== normalized) {
730	      throw new ValidationError(
731	        `cache entry does not describe key ${normalized}: the same fields hash to ${recomputed}`,
732	      );
733	    }
734	    const manifestKey = normalized;
735	    if (this.store.hasManifest(manifestKey)) {
736	      throw new ConflictError(`cache entry ${normalized} already exists`);
737	    }
738	    const digest = await this.store.writeBlob(buffer);
739	    // A remote entry carries no resolved dependency keys, so it is only ever
740	    // reachable as the entry of a root node - exactly the entries a peer can
741	    // hand over without shipping its whole graph.
742	    const manifest = buildManifest({
743	      actionId: entry.action_id ?? 'remote',
744	      key: normalized,
745	      command,
746	      inputs,
747	      env,
748	      dependencies: [],
749	      digest,
750	      size: buffer.length,
751	    });
752	    await this.store.writeManifest(manifestKey, manifest);
753	    this.bump('remote_writes');
754	    this.bump('cache_writes');
755	    await this.persistStats();
756	    return manifest;
757	  }
