772	  // --------------------------------------------------------------------- gc
773	
774	  // Cache retention. The keep set is the node keys of every registered graph's
775	  // last run plus whatever the caller asked to keep; a graph that never ran
776	  // contributes nothing. Every manifest is scanned and validated first, so a
777	  // corrupt store fails the whole request before a single object is deleted.
778	  // Everything outside the keep set is collected: the manifests, the blobs only
779	  // they referenced, and orphan blobs. A dry run reports the exact same sets
780	  // and byte counts without deleting anything.
781	  async gc(request = {}) {
782	    await this.loading;
783	    if (!isPlainObject(request)) throw new ValidationError('gc request must be a JSON object');
784	    rejectUnknown(request, ['keep', 'dry_run'], 'gc request');
785	    const dryRun = request.dry_run === undefined ? false : request.dry_run;
786	    if (typeof dryRun !== 'boolean') throw new ValidationError('gc dry_run must be a boolean');
787	    const keepRequested = new Set();
788	    if (request.keep !== undefined) {
789	      if (!Array.isArray(request.keep)) throw new ValidationError('gc keep must be an array of cache keys');
790	      for (const key of request.keep) keepRequested.add(assertCacheKey(key));
791	    }
792	
793	    const keep = new Set(keepRequested);
794	    for (const run of this.runs.values()) {
795	      for (const node of run.nodes) keep.add(node.key);
796	    }
797	
798	    // Validate before anything is deleted: an unreadable manifest, a key
799	    // mismatch, a missing or dishonest digest, or a missing or tampered blob
800	    // fails the request and leaves the store untouched.
801	    const keys = await this.store.listKeys(Number.MAX_SAFE_INTEGER);
802	    const manifests = new Map();
803	    for (const key of keys) {
804	      const manifest = await this.store.readManifest(key);
805	      const digest = assertDigest(manifest.digest, `cache manifest for key ${key} digest`);
806	      const hexDigest = digest.slice('sha256:'.length);
807	      let buffer;
808	      try {
809	        buffer = await readFile(this.store.blobPath(hexDigest));
810	      } catch (error) {
811	        if (error.code === 'ENOENT') {
812	          throw new ValidationError(
813	            `cache manifest for key ${key} references a blob that is missing from the object store`,
814	          );
815	        }
816	        throw error;
817	      }
818	      if (digestOf(buffer) !== digest) {
819	        throw new ValidationError(`blob referenced by cache manifest for key ${key} does not match its digest`);
820	      }
821	      manifests.set(key, hexDigest);
822	    }
823	
824	    for (const key of keepRequested) {
825	      if (!manifests.has(key)) throw new NotFoundError(`keep key ${key} does not name a cache entry`);
826	    }
827	
828	    const keptKeys = keys.filter((key) => keep.has(key));
829	    const removedKeys = keys.filter((key) => !keep.has(key));
830	    const keptDigests = new Set(keptKeys.map((key) => manifests.get(key)));
831	
832	    const blobSizes = new Map();
833	    for (const hexDigest of await this.store.listBlobDigests()) {
834	      blobSizes.set(hexDigest, (await stat(this.store.blobPath(hexDigest))).size);
835	    }
836	    let keptBytes = 0;
837	    for (const hexDigest of keptDigests) keptBytes += blobSizes.get(hexDigest);
838	    const removedDigests = [...blobSizes.keys()].filter((hexDigest) => !keptDigests.has(hexDigest));
839	    let removedBytes = 0;
840	    for (const hexDigest of removedDigests) removedBytes += blobSizes.get(hexDigest);
841	
842	    if (!dryRun) {
843	      for (const key of removedKeys) await this.store.deleteManifest(key);
844	      for (const hexDigest of removedDigests) await this.store.deleteBlob(hexDigest);
845	    }
846	
847	    return {
848	      dry_run: dryRun,
849	      kept_keys: keptKeys,
850	      removed_keys: removedKeys,
851	      removed_digests: removedDigests.map((hexDigest) => `sha256:${hexDigest}`),
852	      kept_bytes: keptBytes,
853	      removed_bytes: removedBytes,
854	    };
855	  }
856	
857	  // ----------------------------------------------------------- idempotency
858	
859	  async recall(operation, idempotencyKey) {
860	    await this.loading;
861	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return null;
862	    if (idempotencyKey.length > 255) {
863	      throw new ValidationError('Idempotency-Key must be at most 255 characters');
864	    }
865	    const record = await this.store.readMeta(
866	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
867	    );
868	    return record ? { status: record.status, body: record.body } : null;
869	  }
870	
871	  async remember(operation, idempotencyKey, response) {
872	    await this.loading;
873	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return;
874	    await this.store.writeMeta(
875	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
876	      {
877	        schema: 'cachelattice/idempotency/v1',
878	        operation,
879	        status: response.status,
880	        body: response.body,
881	      },
882	    );
883	  }
884	
885	  // A cache entry is valid for a node when the manifest's hashed fields still
886	  // describe the action the node runs: same command, same input digests, same
887	  // environment variable names. The action_id is provenance only - two
888	  // differently named actions with the same definition legitimately share one
889	  // entry, and the first one to run wins the label.
890	  assertManifestMatches(manifest, action, key) {
891	    if (manifest.key !== key) {
892	      throw new ConflictError(`cache entry ${key} claims to belong to ${manifest.key}`);
893	    }
894	    const shape = (command, inputs, envNames) =>
895	      canonicalJson({ command, inputs, env_names: envNames });
896	    if (
897	      shape(manifest.command, manifest.inputs, manifest.env.names) !==
898	      shape(action.command, action.inputs, action.env.names)
899	    ) {
900	      throw new ConflictError(`cache entry for ${key} was produced from different inputs`);
901	    }
902	  }
903	}
904	
905	export async function readWorkspaceFile(workspace, relative) {
906	  const absolute = path.join(workspace, relative);
907	  if (absolute !== workspace && !absolute.startsWith(workspace + path.sep)) {
908	    throw new ValidationError(`path escapes the workspace: ${relative}`);
909	  }
910	  let info;
911	  try {
912	    info = await stat(absolute);
913	  } catch (error) {
914	    if (error.code === 'ENOENT') throw new ValidationError(`input file does not exist: ${relative}`);
915	    throw error;
916	  }
917	  if (!info.isFile()) throw new ValidationError(`input path is not a regular file: ${relative}`);
918	  return readFile(absolute);
919	}
