1	import path from 'node:path';
2	
3	import { assertDigest, canonicalJson, sha256Text } from './canonical.js';
4	import { ValidationError } from './errors.js';
5	
6	export const KEY_SCHEMA = 'cachelattice/action-key/v1';
7	
8	const NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
9	const HASH = /^[0-9a-f]{64}$/;
10	
11	// Hash inputs reference another action by its action key, which is plain
12	// lowercase hex - no algorithm prefix, so that a key can be pasted straight out
13	// of a cache response into the next action's input list.
14	export function assertHash(value, label) {
15	  if (typeof value !== 'string' || !HASH.test(value)) {
16	    throw new ValidationError(`${label} must be 64 lowercase hex characters, received ${JSON.stringify(value)}`);
17	  }
18	  return value;
19	}
20	
21	export function assertName(value, label) {
22	  if (typeof value !== 'string' || !NAME.test(value)) {
23	    throw new ValidationError(
24	      `${label} must match [A-Za-z0-9][A-Za-z0-9._-]{0,63}`,
25	    );
26	  }
27	  return value;
28	}
29	
30	// Workspace-relative paths are normalized once, before anything else looks at
31	// them, so that "./a/b.txt", "a/./b.txt" and "a/b.txt" are one and the same
32	// input everywhere: in the key, in the file access, and in the error messages.
33	export function normalizePath(value, label = 'path') {
34	  if (typeof value !== 'string' || value.length === 0) {
35	    throw new ValidationError(`${label} must be a non-empty string`);
36	  }
37	  if (value.includes('\0')) throw new ValidationError(`${label} must not contain NUL`);
38	  const candidate = value.split('\\').join('/');
39	  if (candidate.startsWith('/') || /^[A-Za-z]:/.test(candidate)) {
40	    throw new ValidationError(`${label} must be relative to the workspace: ${value}`);
41	  }
