node --test tests/ 2>&1 | tail -8 && node --input-type=module -e "
import { mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { Cachelattice } from './src/service.js';

const root = await mkdtemp(path.join(tmpdir(), 'cachelattice-reload-'));
const workspace = path.join(root, 'workspace');
await mkdir(path.join(workspace, 'src'), { recursive: true });
await writeFile(path.join(workspace, 'src', 'app.txt'), 'alpha\n');
const opts = { dataDirectory: path.join(root, 'data'), workspace, ambientEnv: {} };

const first = new Cachelattice(opts);
await first.loading;
await first.putAction({ name: 'w', command: { kind: 'write-file', content: 'x' }, inputs: [{ kind: 'file', path: 'src/app.txt' }], env: [] });
await first.putGraph('g', { id: 'g', limits: { cpu: 2 }, nodes: [{ id: 'a', action: 'w', resources: { cpu: 1 } }] });

// Simulate a restart: a fresh service over the same data directory.
const second = new Cachelattice(opts);
await second.loading;
const graph = await second.getGraph('g');
console.log('limits after reload:', JSON.stringify(graph.limits));
console.log('resources after reload:', JSON.stringify(graph.nodes[0].resources));
const run = await second.runGraph('g');
console.log('run resource_limits:', JSON.stringify(run.resource_limits), 'peak:', JSON.stringify(run.peak_resources));
await rm(root, { recursive: true, force: true });
"
